// ============================================================================
// Type Definitions and Type Aliases
// ============================================================================

object TokenizerTypes {
  type StrOrBytes = String
  type JsonValue = Any
}

// ============================================================================
// TokenType - Sealed Trait Hierarchy
// ============================================================================

sealed trait TokenType extends Product with Serializable

object TokenType {
  case object STRING extends TokenType
  case object NUMERIC extends TokenType
  case object TEMPORAL extends TokenType
  case object STRUCTURED extends TokenType
  case object BINARY extends TokenType
  case object NULL extends TokenType

  def fromString(value: String): Option[TokenType] = value match {
    case "string" => Some(STRING)
    case "numeric" => Some(NUMERIC)
    case "temporal" => Some(TEMPORAL)
    case "structured" => Some(STRUCTURED)
    case "binary" => Some(BINARY)
    case "null" => Some(NULL)
    case _ => None
  }
}

// ============================================================================
// Core Token Class - Immutable Case Class
// ============================================================================

case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty[String, Any]
) {
  def withMetadata(additionalMetadata: (String, Any)*): Token = {
    val newMetadata = metadata ++ additionalMetadata
    copy(metadata = newMetadata)
  }
}

// ============================================================================
// Tokenizable Type Class
// ============================================================================

trait Tokenizable[-T] {
  def toToken(value: T): String
}

object Tokenizable {
  implicit object StringTokenizable extends Tokenizable[String] {
    def toToken(value: String): String = value
  }

  implicit def optionTokenizable[T: Tokenizable]: Tokenizable[Option[T]] = {
    new Tokenizable[Option[T]] {
      def toToken(value: Option[T]): String = value match {
        case Some(v) => implicitly[Tokenizable[T]].toToken(v)
        case None => "NULL"
      }
    }
  }

  implicit def listTokenizable[T: Tokenizable]: Tokenizable[List[T]] = {
    new Tokenizable[List[T]] {
      def toToken(value: List[T]): String = {
        val ev = implicitly[Tokenizable[T]]
        value.map(ev.toToken).mkString(",")
      }
    }
  }

  implicit def mapTokenizable[K: Tokenizable, V: Tokenizable]: Tokenizable[Map[K, V]] = {
    new Tokenizable[Map[K, V]] {
      def toToken(value: Map[K, V]): String = {
        val kEv = implicitly[Tokenizable[K]]
        val vEv = implicitly[Tokenizable[V]]
        value.map { case (k, v) => s"${kEv.toToken(k)}=${vEv.toToken(v)}" }.toSeq.sorted.mkString("{", ",", "}")
      }
    }
  }
}

// ============================================================================
// Abstract Base Tokenizer
// ============================================================================

abstract class BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

// ============================================================================
// String Tokenizer
// ============================================================================

class StringTokenizer(
    encoding: String = "utf-8",
    normalizer: String => String = identity
) extends BaseTokenizer[String] {

  override def tokenize(value: String): Token = {
    val normalized = normalizer(value)
    Token(normalized, TokenType.STRING)
  }
}

// ============================================================================
// Numeric Tokenizer
// ============================================================================

class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {

  override def tokenize(value: Any): Token = value match {
    case decimal: BigDecimal =>
      val formatted = decimal.setScale(precision, BigDecimal.RoundingMode.HALF_UP)
      Token(formatted.toString, TokenType.NUMERIC, Map("originalType" -> "BigDecimal"))
    case float: Float =>
      Token(f"$float%${precision}.${precision}f", TokenType.NUMERIC, Map("originalType" -> "Float"))
    case int: Int =>
      Token(int.toString, TokenType.NUMERIC, Map("originalType" -> "Int"))
    case double: Double =>
      Token(f"$double%${precision}.${precision}f", TokenType.NUMERIC, Map("originalType" -> "Double"))
    case other =>
      Token(other.toString, TokenType.NUMERIC, Map("originalType" -> other.getClass.getSimpleName))
  }
}

// ============================================================================
// Temporal Tokenizer
// ============================================================================

class TemporalTokenizer(
    formatStr: Option[String] = None
) extends BaseTokenizer[TemporalToken] {

  override def tokenize(value: TemporalToken): Token = {
    val formatter = formatStr
      .map(DateTimeFormatter.ofPattern)
      .getOrElse {
        value match {
          case _: TemporalToken.ZonedDateTimeValue => DateTimeFormatter.ISO_LOCAL_DATE_TIME
          case _: TemporalToken.LocalDateTimeValue => DateTimeFormatter.ISO_LOCAL_DATE_TIME
          case _: TemporalToken.LocalDateValue => DateTimeFormatter.ISO_LOCAL_DATE
        }
      }

    val formatted = value match {
      case TemporalToken.ZonedDateTimeValue(zdt) => zdt.format(formatter)
      case TemporalToken.LocalDateTimeValue(ldt) => ldt.format(formatter)
      case TemporalToken.LocalDateValue(ld) => ld.format(formatter)
    }

    Token(formatted, TokenType.TEMPORAL)
  }
}

sealed trait TemporalToken

object TemporalToken {
  case class LocalDateTimeValue(value: LocalDateTime) extends TemporalToken
  case class ZonedDateTimeValue(value: ZonedDateTime) extends TemporalToken
  case class LocalDateValue(value: LocalDate) extends TemporalToken

  def apply(ldt: LocalDateTime): TemporalToken = LocalDateTimeValue(ldt)
  def apply(zdt: ZonedDateTime): TemporalToken = ZonedDateTimeValue(zdt)
  def apply(ld: LocalDate): TemporalToken = LocalDateValue(ld)
}

// ============================================================================
// Universal Tokenizer - Handles Multiple Types
// ============================================================================

class UniversalTokenizer(
    stringTokenizer: StringTokenizer = new StringTokenizer(),
    numericTokenizer: NumericTokenizer = new NumericTokenizer(),
    temporalTokenizer: TemporalTokenizer = new TemporalTokenizer()
) {

  def tokenize(value: Any): Token = value match {
    case null => Token("NULL", TokenType.NULL)

    case tokenizable: Tokenizable =>
      Token(tokenizable.toToken, TokenType.STRUCTURED)

    case str: String =>
      stringTokenizer.tokenize(str)

    case bytes: Array[Byte] =>
      stringTokenizer.tokenize(new String(bytes, stringTokenizer.encoding))

    case int: Int =>
      numericTokenizer.tokenize(int)

    case float: Float =>
      numericTokenizer.tokenize(float)

    case double: Double =>
      numericTokenizer.tokenize(double)

    case decimal: BigDecimal =>
      numericTokenizer.tokenize(decimal)

    case ldt: LocalDateTime =>
      temporalTokenizer.tokenize(TemporalToken(ldt))

    case zdt: ZonedDateTime =>
      temporalTokenizer.tokenize(TemporalToken(zdt))

    case ld: LocalDate =>
      temporalTokenizer.tokenize(TemporalToken(ld))

    // Fallback: convert to string
    case other =>
      Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }

  def tokenizeBatch(values: Iterable[Any]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer
// ============================================================================

class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {

  private val punctuation = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def processToken(word: String): Option[String] = {
    val processed = if (stripPunctuation) {
      word.filterNot(punctuation.contains)
    } else {
      word
    }

    val lowered = if (lowercase) {
      processed.toLowerCase
    } else {
      processed
    }

    if (lowered.length < minLength) {
      None
    } else {
      val truncated = maxLength match {
        case Some(max) if lowered.length > max => lowered.take(max)
        case _ => lowered
      }
      if (truncated.isEmpty) None else Some(truncated)
    }
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+")
    words.view.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          processed,
          TokenType.STRING,
          Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] = {
    tokenize(text).map(_.value)
  }

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    text.split("\\s+").foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int = {
    tokenize(text).size
  }
}

