  private var metadata: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(meta: (String, Any)*): TokenizerBuilder[T] = {
    metadata = metadata ++ meta
    this
  }

  def build(): T => Token = { value: T =>
    // Validate
    validators.find(!_(value)).foreach { _ =>
      throw new IllegalArgumentException(s"Validation failed for $value")
    }

    // Convert to string
    var strValue = value.toString

    // Normalize
    normalizers.foreach { normalizer =>
      strValue = normalizer(strValue)
    }

    Token(strValue, TokenType.STRING, metadata)
  }
}

// ============================================================================
// Companion Objects and Factory Methods
// ============================================================================

object Tokenizer {

  // Global instance for convenience
  val universal: UniversalTokenizer = new UniversalTokenizer()

  // Factory methods for convenience
  def stringTokenizer(encoding: String = "utf-8",
                      normalizer: String => String = identity): StringTokenizer = {
    new StringTokenizer(encoding, normalizer)
  }

  def numericTokenizer(precision: Int = 6,
                       formatOptions: Map[String, Any] = Map.empty): NumericTokenizer = {
    new NumericTokenizer(precision, formatOptions)
  }

  def temporalTokenizer(formatStr: Option[String] = None): TemporalTokenizer = {
    new TemporalTokenizer(formatStr)
  }

  def whitespaceTokenizer(lowercase: Boolean = false,
                           minLength: Int = 0,
                           maxLength: Option[Int] = None,
                           stripPunctuation: Boolean = false): WhitespaceTokenizer = {
    new WhitespaceTokenizer(lowercase, minLength, maxLength, stripPunctuation)
  }

  // Type class instances for common types
  implicit val stringTokenizable: Tokenizable[String] = (value: String) => value

  implicit def optionTokenizable[T: Tokenizable]: Tokenizable[Option[T]] = {
    case Some(value) => value.toToken
    case None => "NULL"
  }

  implicit def listTokenizable[T: Tokenizable]: Tokenizable[List[T]] = {
    values => values.map(_.toToken).mkString(",")
  }

  implicit def mapTokenizable[K: Tokenizable, V: Tokenizable]: Tokenizable[Map[K, V]] = {
    map => map.map { case (k, v) => s"${k.toToken}=${v.toToken}" }.toSeq.sorted.mkString("{", ",", "}")
  }
}

// ============================================================================
// Convenience Functions
// ============================================================================

object Tokenize {

  // Single value tokenization
  def apply(value: Any): Token = Tokenizer.universal.tokenize(value)

  def apply(value: Any, metadata: (String, Any)*): Token = {
    Tokenizer.universal.tokenize(value).withMetadata(metadata: _*)
  }

  // Batch tokenization
  def batch(values: Iterable[Any]): Iterator[Token] = {
    Tokenizer.universal.tokenizeBatch(values)
  }

  def batch(values: Iterable[Any], metadata: (String, Any)*): Iterator[Token] = {
    batch(values).map(_.withMetadata(metadata: _*))
  }

  // Convert to token with metadata
  def toToken(value: Any, metadata: (String, Any)*): Token = {
    apply(value, metadata: _*)
  }

  // Add metadata to existing token
  def withMetadata(token: Token, metadata: (String, Any)*): Token = {
    token.withMetadata(metadata: _*)
  }

  // Specific tokenizer functions
  def string(value: String, encoding: String = "utf-8", normalizer: String => String = identity): Token = {
    new StringTokenizer(encoding, normalizer).tokenize(value)
  }

  def numeric(value: Any, precision: Int = 6): Token = {
    new NumericTokenizer(precision).tokenize(value)
  }

  def temporal(value: TemporalToken, formatStr: Option[String] = None): Token = {
    new TemporalTokenizer(formatStr).tokenize(value)
  }

  def whitespace(
      text: String,
      lowercase: Boolean = false,
      minLength: Int = 0,
      maxLength: Option[Int] = None,
      stripPunctuation: Boolean = false
  ): List[Token] = {
    new WhitespaceTokenizer(lowercase, minLength, maxLength, stripPunctuation).tokenize(text)
  }
}

// ============================================================================
// Examples and Usage
// ============================================================================

object TokenizerExamples extends App {

  // Example 1: Basic tokenization
  val tokens = Tokenize.batch(List("Hello", 42, 3.14))
  tokens.foreach(println)

  // Example 2: Whitespace tokenizer
  val whitespaceTokens = Tokenize.whitespace("Hello, World! How are you?", stripPunctuation = true)
  whitespaceTokens.foreach(println)

  // Example 3: Builder pattern
  val customTokenizer = new TokenizerBuilder[String]()
    .withNormalizer(_.toLowerCase)
    .withValidator(_.nonEmpty)
    .withMetadata("source" -> "builder")
    .build()

  val customToken = customTokenizer("CUSTOM")
  println(customToken)

  // Example 4: Type class usage
  val tokenizableValue = "test"
  val tokenized = Tokenizable.StringTokenizable.toToken(tokenizableValue)
  println(tokenized)
}

